/// <summary>
/// Handles the DSD Fee process, including calculation, reporting, and optional journal creation.
/// </summary>
public class AVARUMDSDFeeManager extends RunBaseReport
{
    Query localQuery;
    QueryRun localQueryRun;
    str aCode;
    real fee;
    FromDate aFromDate;
    ToDate aToDate;
    NoYes doPrint;
    AllOpenPosted doPosted;
    NoYes createJournal;
    str lastClass;
    DialogField dialogFromDate;
    DialogField dialogToDate;
    DialogField dialogPosted;
    DialogField dialogPrint;
    DialogField dialogCreateJournal;
    AVARUMDSDFeeTable feeTable;
    AVARUMDSDFeeTable feeTableTmp;
    Map recordsForUpdate;
    NumberSequenceCode numberSequenceCode;

    #define.CurrentVersion(5)
    #localmacro.CurrentList
        aFromDate,
        aToDate,
        doPrint,
        doPosted,
        createJournal
    #endmacro

}

